@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

@theme inline {
  --font-sans: "Plus Jakarta Sans", sans-serif;
  --font-serif: "Lora", serif;

  --radius-sm: 0.5rem;
  --radius-md: 0.75rem;
  --radius-lg: 1rem;
  --radius-xl: 1.5rem;

  /* Vedic/Saffron Color Palette */
  /* Saffron: #FF9933 -> H: 30, S: 100%, L: 60% */
  /* Green: #138808 -> H: 115, S: 90%, L: 28% */
  /* Navy: #000080 -> H: 240, S: 100%, L: 25% */
  /* BG: #FFFAF0 -> H: 40, S: 50%, L: 97% (Floral White) */

  --color-background: hsl(40 50% 97%);
  --color-foreground: hsl(210 10% 20%);

