import { motion, AnimatePresence } from "framer-motion";
import { useState, useEffect } from "react";

// Create a motion component for the SVG stop element to animate gradients
const MotionStop = motion.create("stop");

export function SplashScreen() {
  // Dynamic Vedic Color Palettes
  const palettes = [
    {
      name: "Agni (Fire)",
      primary: "#FF9933", // Saffron
      secondary: "#FFC107", // Gold
      accent: "#D32F2F", // Kumkum Red
      text: "#BF360C", // Deep Brown
      bg: "#FFF3E0" // Light Orange tint
    },
    {
      name: "Akasha (Sky/Krishna)",
      primary: "#039BE5", // Sky Blue
      secondary: "#4FC3F7", // Light Blue
      accent: "#FFD700", // Gold
      text: "#01579B", // Deep Blue
      bg: "#E1F5FE" // Light Blue tint
    },
    {
      name: "Prakriti (Nature)",
      primary: "#43A047", // Leaf Green
      secondary: "#81C784", // Light Green
      accent: "#FFEB3B", // Flower Yellow
      text: "#1B5E20", // Deep Green
      bg: "#E8F5E9" // Light Green tint
    },
    {
      name: "Shakti (Power)",
      primary: "#C2185B", // Pink/Red
      secondary: "#F48FB1", // Light Pink
      accent: "#FFC107", // Gold
      text: "#880E4F", // Deep Maroon
      bg: "#FCE4EC" // Light Pink tint
    }
  ];

  const [currentPaletteIndex, setCurrentPaletteIndex] = useState(0);

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentPaletteIndex((prev) => (prev + 1) % palettes.length);
    }, 3000); // Change palette every 3 seconds
    return () => clearInterval(timer);
  }, []);

  const colors = palettes[currentPaletteIndex];

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center overflow-hidden">
      {/* Animated Background Overlay */}
      <motion.div 
        className="absolute inset-0 bg-background/95 backdrop-blur-md"
        transition={{ duration: 1.5 }}
      />

      <div className="relative flex flex-col items-center justify-center z-10">

        {/* Main Container */}
        <div className="relative w-64 h-64 flex items-center justify-center">

          {/* Layer 1: Rotating Mandala / Chakra (SVG) */}
          <motion.svg
            viewBox="0 0 100 100"
            className="absolute inset-0 w-full h-full"
            animate={{ rotate: 360 }}
            transition={{ duration: 30, repeat: Infinity, ease: "linear" }}
          >
            {/* Outer Ring */}
            <motion.circle 
              cx="50" cy="50" r="48" fill="none" strokeWidth="0.5" opacity="0.8"
              animate={{ stroke: colors.primary }}
              transition={{ duration: 1 }}
            />
            <motion.path 
              d="M50 2 A48 48 0 0 1 50 98 A48 48 0 0 1 50 2 Z" fill="none" strokeWidth="0.5" strokeDasharray="2 4" opacity="0.6"
              animate={{ stroke: colors.primary }}
              transition={{ duration: 1 }}
            />

            {/* Radiating Lines */}
            {[0, 45, 90, 135, 180, 225, 270, 315].map((deg) => (
              <motion.path
                key={deg}
                d="M50 50 L50 15"
                strokeWidth="0.3"
                transform={`rotate(${deg} 50 50)`}
                opacity="0.7"
                animate={{ stroke: colors.secondary }}
                transition={{ duration: 1 }}
              />
            ))}

            {/* Swasti Symbols (卐) */}
            {[0, 90, 180, 270].map((deg) => (
              <g key={deg} transform={`rotate(${deg} 50 50)`}>
                <motion.text 
                  x="50" 
                  y="10" 
                  fontSize="8" 
                  fontWeight="bold"
                  textAnchor="middle" 
                  dominantBaseline="middle"
                  style={{ filter: "drop-shadow(0px 0px 2px rgba(0,0,0,0.1))" }}
                  animate={{ fill: colors.accent }}
                  transition={{ duration: 1 }}
                >
                  卐
                </motion.text>
              </g>
            ))}

            {/* Decorative Dots */}
            {[22.5, 67.5, 112.5, 157.5, 202.5, 247.5, 292.5, 337.5].map((deg) => (
              <motion.circle
                key={deg}
                cx="50"
                cy="25"
                r="1.5"
                transform={`rotate(${deg} 50 50)`}
                opacity="0.8"
                animate={{ fill: colors.primary }}
                transition={{ duration: 1 }}
              />
            ))}
          </motion.svg>

          {/* Layer 2: Pulse Rings */}
          <motion.div
            className="absolute w-44 h-44 rounded-full border"
            animate={{ 
              scale: [1, 1.05, 1], 
              opacity: [0.2, 0.5, 0.2],
              borderColor: colors.primary 
            }}
            transition={{ duration: 4, repeat: Infinity, ease: "easeInOut" }}
          />
           <motion.div
            className="absolute w-36 h-36 rounded-full border"
            animate={{ 
              scale: [1.05, 1, 1.05], 
              opacity: [0.2, 0.5, 0.2],
              borderColor: colors.secondary
            }}
            transition={{ duration: 4, repeat: Infinity, ease: "easeInOut" }}
          />

          {/* Layer 3: The Golden Lotus (SVG) */}
          <motion.svg
            viewBox="0 0 200 200"
            className="absolute w-32 h-32 drop-shadow-lg"
            initial={{ opacity: 0, scale: 0.8 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ duration: 1 }}
          >
            <defs>
              <linearGradient id="lotusGradient" x1="0%" y1="0%" x2="100%" y2="100%">
                <MotionStop offset="0%" animate={{ stopColor: colors.secondary }} transition={{ duration: 1 }} />
                <MotionStop offset="100%" animate={{ stopColor: colors.primary }} transition={{ duration: 1 }} />
              </linearGradient>
            </defs>

            {/* Stylized Lotus Petals */}
            {[0, 90, 180, 270].map((rotation, i) => (
               <motion.path
                key={i}
                d="M100 40 C100 40 130 80 100 100 C70 80 100 40 100 40"
                fill="url(#lotusGradient)"
                opacity="0.9"
                transform={`rotate(${rotation} 100 100)`}
                animate={{ 
                  d: [
                    "M100 40 C100 40 130 80 100 100 C70 80 100 40 100 40", 
                    "M100 35 C100 35 135 80 100 100 C65 80 100 35 100 35"
                  ]
                }}
                transition={{ duration: 3, repeat: Infinity, repeatType: "reverse", ease: "easeInOut" }}
              />
            ))}

            {/* Center Glow */}
            <circle cx="100" cy="100" r="20" fill="#FFFFFF" className="blur-xl opacity-60" />
          </motion.svg>

          {/* Layer 4: The Divine OM */}
          <motion.div
            className="absolute z-20 text-5xl font-serif font-bold"
            initial={{ opacity: 0, scale: 0.5 }}
            animate={{ 
              opacity: 1, 
              scale: 1,
              color: colors.text,
              textShadow: `0 0 20px ${colors.secondary}80`
            }}
            transition={{ duration: 1.5, ease: "easeOut" }}
          >
            ॐ
          </motion.div>
        </div>

        {/* Text */}
        <motion.div
          className="mt-10 flex flex-col items-center gap-2"
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.5 }}
        >
          <motion.div 
            className="h-px w-24"
            animate={{ 
              background: `linear-gradient(90deg, transparent, ${colors.primary}, transparent)` 
            }}
          />
          <motion.p 
            className="text-sm font-medium tracking-[0.4em] uppercase"
            animate={{ color: colors.text }}
          >
            Focus
          </motion.p>
          <motion.div 
            className="h-px w-24"
            animate={{ 
              background: `linear-gradient(90deg, transparent, ${colors.primary}, transparent)` 
            }}
          />
        </motion.div>

      </div>
    </div>
  );
}

client/src/pages/Wallet.tsx.content:
import { PageTransition } from "@/components/PageTransition";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { Wallet, CreditCard, ShieldCheck, Zap, Gift, Lock, UserCheck, Headset, Smartphone, Loader2, CheckCircle } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { useState, useEffect } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { useLocation } from "wouter";

declare global {
  interface Window {
    Razorpay: any;
  }
}

interface WalletData {
  id: string;
  balance: string;
  totalRecharged: string;
}

interface RechargePack {
  amount: number;
  bonus: number;
  tag: string | null;
}

export default function WalletPage() {
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [location] = useLocation();
  const [selectedPack, setSelectedPack] = useState<RechargePack | null>(null);
  const [paymentDialogOpen, setPaymentDialogOpen] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [razorpayLoaded, setRazorpayLoaded] = useState(false);

  const { data: wallet, isLoading: walletLoading } = useQuery<{ wallet: WalletData }>({
    queryKey: ["/api/wallet"],
    queryFn: async () => {
      const res = await fetch("/api/wallet", { credentials: "include" });
      if (!res.ok) throw new Error("Failed to fetch wallet");
      return res.json();
    },
  });

  useEffect(() => {
    const script = document.createElement("script");
    script.src = "https://checkout.razorpay.com/v1/checkout.js";
    script.async = true;
    script.onload = () => setRazorpayLoaded(true);
    document.body.appendChild(script);
    return () => {
      document.body.removeChild(script);
    };
  }, []);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    if (params.get("success") === "true") {
      const amount = params.get("amount");
      toast({
        title: "Payment Successful!",
        description: `₹${amount} has been added to your wallet.`,
      });
      queryClient.invalidateQueries({ queryKey: ["/api/wallet"] });
      window.history.replaceState({}, "", "/wallet");
    } else if (params.get("canceled") === "true") {
      toast({
        title: "Payment Cancelled",
        description: "Your payment was cancelled. No amount was charged.",
        variant: "destructive",
      });
      window.history.replaceState({}, "", "/wallet");
    }
  }, [location, queryClient, toast]);

  const rechargePacks: RechargePack[] = [
    { amount: 200, bonus: 0, tag: null },
    { amount: 500, bonus: 50, tag: "Popular" },
    { amount: 1000, bonus: 150, tag: "Best Value" },
    { amount: 2000, bonus: 400, tag: "Super Saver" },
    { amount: 5000, bonus: 1200, tag: null },
    { amount: 10000, bonus: 3000, tag: "Mega Pack" },
  ];

  const handleSelectPack = (pack: RechargePack) => {
    setSelectedPack(pack);
    setPaymentDialogOpen(true);
  };

  const handleUPIPayment = async () => {
    if (!selectedPack || !razorpayLoaded) return;

    setIsProcessing(true);
    try {
      const orderRes = await fetch("/api/wallet/razorpay-order", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({
          amount: selectedPack.amount,
          packName: `Wallet Recharge - ₹${selectedPack.amount}`,
        }),
      });

      if (!orderRes.ok) {
        const error = await orderRes.json();
        throw new Error(error.error || "Failed to create order");
      }

      const orderData = await orderRes.json();

      const options = {
        key: orderData.keyId,
        amount: orderData.amount,
        currency: orderData.currency,
        name: "Focus",
        description: `Add ₹${selectedPack.amount} to your wallet`,
        order_id: orderData.orderId,
        handler: async (response: any) => {
          try {
            const verifyRes = await fetch("/api/wallet/razorpay-verify", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              credentials: "include",
              body: JSON.stringify({
                razorpay_order_id: response.razorpay_order_id,
                razorpay_payment_id: response.razorpay_payment_id,
                razorpay_signature: response.razorpay_signature,
                amount: selectedPack.amount,
              }),
            });

            if (verifyRes.ok) {
              toast({
                title: "Payment Successful!",
                description: `₹${selectedPack.amount} has been added to your wallet via UPI.`,
              });
              queryClient.invalidateQueries({ queryKey: ["/api/wallet"] });
            } else {
              throw new Error("Payment verification failed");
            }
          } catch (err) {
            toast({
              title: "Payment Error",
              description: "There was an issue verifying your payment. Please contact support.",
              variant: "destructive",
            });
          }
        },
        prefill: {},
        theme: {
          color: "#e07c00",
        },
        modal: {
          ondismiss: () => {
            setIsProcessing(false);
          },
        },
      };

      const rzp = new window.Razorpay(options);
      rzp.open();
      setPaymentDialogOpen(false);
    } catch (error: any) {
      toast({
        title: "Error",
        description: error.message || "Failed to initiate UPI payment",
        variant: "destructive",
      });
    } finally {
      setIsProcessing(false);
    }
  };

  const handleCardPayment = async () => {
    if (!selectedPack) return;

    setIsProcessing(true);
    try {
      const res = await fetch("/api/wallet/checkout", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({
          amount: selectedPack.amount,
          packName: `Wallet Recharge - ₹${selectedPack.amount}`,
        }),
      });

      if (!res.ok) {
        const error = await res.json();
        throw new Error(error.error || "Failed to create checkout session");
      }

      const { url } = await res.json();
      window.location.href = url;
    } catch (error: any) {
      toast({
        title: "Error",
        description: error.message || "Failed to initiate card payment",
        variant: "destructive",
      });
      setIsProcessing(false);
    }
  };

  const walletBalance = wallet?.wallet?.balance || "0.00";

  return (
    <PageTransition>
      <div className="min-h-screen bg-muted/30 pb-20">
        <div className="bg-primary text-primary-foreground pt-12 pb-24 rounded-b-[3rem] shadow-lg relative overflow-hidden">
          <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] opacity-10"></div>
          <div className="container mx-auto px-4 relative z-10 text-center">
            <h1 className="text-3xl font-bold mb-2 font-serif">My Wallet</h1>
            <p className="opacity-90 mb-8">Recharge to talk to therapists and gurus</p>

            <div className="bg-white/10 backdrop-blur-md border border-white/20 rounded-2xl p-6 max-w-sm mx-auto flex flex-col items-center">
              <span className="text-sm font-medium opacity-80 mb-1">Current Balance</span>
              {walletLoading ? (
                <Loader2 className="w-8 h-8 animate-spin mt-2" />
              ) : (
                <div className="text-5xl font-bold flex items-start" data-testid="text-wallet-balance">
                  <span className="text-2xl mt-2">₹</span>{parseFloat(walletBalance).toFixed(2)}
                </div>
              )}
            </div>
          </div>
        </div>

        <div className="container mx-auto px-4 -mt-12 relative z-20">
          <div className="grid lg:grid-cols-3 gap-8 max-w-6xl mx-auto">

            <div className="lg:col-span-2 space-y-6">
              <div className="bg-background rounded-3xl shadow-sm border p-6 md:p-8">
                <div className="flex items-center gap-3 mb-6">
                  <div className="w-10 h-10 rounded-full bg-green-100 flex items-center justify-center text-green-600">
                    <Zap className="w-5 h-5" />
                  </div>
                  <div>
                    <h2 className="text-xl font-bold">Add Money to Wallet</h2>
                    <p className="text-sm text-muted-foreground">Balance never expires</p>
                  </div>
                </div>

                <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                  {rechargePacks.map((pack, i) => (
                    <button
                      key={i}
                      onClick={() => handleSelectPack(pack)}
                      className="relative group border-2 border-muted hover:border-primary rounded-xl p-4 transition-all hover:shadow-md text-left bg-card"
                      data-testid={`button-pack-${pack.amount}`}
                    >
                      {pack.tag && (
                        <span className="absolute -top-3 left-1/2 -translate-x-1/2 bg-gradient-to-r from-orange-500 to-red-500 text-white text-[10px] font-bold px-2 py-0.5 rounded-full uppercase tracking-wider shadow-sm">
                          {pack.tag}
                        </span>
                      )}
                      <div className="font-bold text-lg mb-1">₹{pack.amount}</div>
                      {pack.bonus > 0 ? (
                        <div className="text-xs text-green-600 font-medium flex items-center gap-1">
                          <Gift className="w-3 h-3" /> Get ₹{pack.bonus} Extra
                        </div>
                      ) : (
                        <div className="text-xs text-muted-foreground">Standard Pack</div>
                      )}
                    </button>
                  ))}
                </div>

                <div className="mt-8 p-4 bg-blue-50 text-blue-800 rounded-xl text-sm flex gap-3 items-start border border-blue-100">
                  <ShieldCheck className="w-5 h-5 shrink-0" />
                  <p>Your payment is 100% secure. We use 256-bit encryption to protect your financial information.</p>
                </div>
              </div>

              <div className="bg-background rounded-3xl shadow-sm border p-6">
                <h3 className="font-bold text-lg mb-4">Recent Transactions</h3>
                <div className="text-center py-8 text-muted-foreground text-sm">
                  No transactions yet. Recharge to start your journey.
                </div>
              </div>
            </div>

            <div className="space-y-6">
              <Card className="border-0 shadow-lg bg-gradient-to-br from-slate-900 to-slate-800 text-white overflow-hidden relative">
                <div className="absolute top-0 right-0 w-32 h-32 bg-primary/20 rounded-full blur-3xl -mr-16 -mt-16"></div>
                <CardContent className="p-6 relative z-10">
                  <h3 className="font-bold text-xl mb-4">Why Recharge?</h3>
                  <ul className="space-y-4">
                    <li className="flex gap-3">
                      <div className="w-8 h-8 rounded-full bg-white/10 flex items-center justify-center shrink-0">
                        <Wallet className="w-4 h-4" />
                      </div>
                      <div>
                        <div className="font-semibold">Pay per minute</div>
                        <div className="text-sm text-white/70">Only pay for the time you speak</div>
                      </div>
                    </li>
                    <li className="flex gap-3">
                      <div className="w-8 h-8 rounded-full bg-white/10 flex items-center justify-center shrink-0">
                        <ShieldCheck className="w-4 h-4" />
                      </div>
                      <div>
                        <div className="font-semibold">Money Back Guarantee</div>
                        <div className="text-sm text-white/70">If you're not satisfied with the session</div>
                      </div>
                    </li>
                  </ul>
                  <Button className="w-full mt-6 bg-white text-slate-900 hover:bg-white/90 font-bold" variant="secondary">
                    Read Refund Policy
                  </Button>
                </CardContent>
              </Card>

              <div className="bg-background rounded-2xl border p-6">
                 <h3 className="font-bold text-lg mb-4 flex items-center gap-2">
                   <ShieldCheck className="w-5 h-5 text-green-600" />
                   Trust & Safety
                 </h3>
                 <div className="space-y-4">
                   <div className="flex gap-3">
                     <div className="w-8 h-8 rounded-full bg-blue-50 text-blue-600 flex items-center justify-center shrink-0">
                       <Lock className="w-4 h-4" />
                     </div>
                     <div>
                       <div className="font-semibold text-sm">Secure Payments</div>
                       <div className="text-xs text-muted-foreground">256-bit SSL Encrypted</div>
                     </div>
                   </div>
                   <div className="flex gap-3">
                     <div className="w-8 h-8 rounded-full bg-orange-50 text-orange-600 flex items-center justify-center shrink-0">
                       <UserCheck className="w-4 h-4" />
